/** Pictogramele care se potrivesc cu textul căutat (după nume și cuvinte, fără diacritice), din categoria aleasă ('' = toate). */
export function findIcons(q: string, cat = ''): Icon[] {
  const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const words = norm(q).split(/\s+/).filter(Boolean);
  return ICONS.filter((ic) => (!cat || ic.cat === cat) && words.every((w) => norm(ic.name + ' ' + ic.keys).includes(w)));
}

/** Grosimile liniei din fereastra Pictograme și de pe bara imaginii din Docs. */
export const ICON_STROKES: [number, string][] = [[1.5, 'Subțire'], [2, 'Normală'], [2.75, 'Groasă']];

/** Ce rămâne pe poza unei pictograme puse în Docs (atributul data-icon), ca să poată fi recolorată: pictograma, culoarea, grosimea, rotirile. */
export interface IconSpec { id: string; c: string; s: number; t?: string }

export function iconById(id: string): Icon | undefined {
  return ICONS.find((ic) => ic.id === id);
}

/** Citește descrierea unei pictograme de pe imagine; null dacă lipsește, e stricată sau pictograma nu mai există. */
export function parseIconSpec(v: unknown): IconSpec | null {
  let o: unknown = v;
  if (typeof v === 'string') { try { o = JSON.parse(v); } catch { return null; } }
  if (!o || typeof o !== 'object') return null;
  const r = o as Record<string, unknown>;
  if (typeof r.id !== 'string' || !iconById(r.id)) return null;
  const c = typeof r.c === 'string' && /^#[0-9a-f]{6}$/i.test(r.c) ? r.c.toLowerCase() : '#1f4e79';
  const s = Math.min(4, Math.max(1, Number(r.s) || 2));
  const t = typeof r.t === 'string' ? r.t.replace(/[^rlhv]/g, '').slice(-16) : '';
  return { id: r.id, c, s, ...(t ? { t } : {}) };
}

/** Pictograma ca SVG întreg, cu culoarea și grosimea liniei alese. */
export function iconSvg(ic: Icon, color: string, stroke = 2, size = 512): string {
  const body = ic.body.replace(/currentColor/g, color);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-1 -1 26 26" width="${size}" height="${size}" fill="none" stroke="${color}" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;
}

/** Pictograma ca poză PNG transparentă (size × size). */
export function iconPng(ic: Icon, color: string, stroke = 2, size = 512): Promise<Blob> {
  return new Promise((resolve, reject) => {
    const im = new Image();
    im.onload = () => {
      const c = document.createElement('canvas');
      c.width = size; c.height = size;
      c.getContext('2d')!.drawImage(im, 0, 0, size, size);
      c.toBlob((b) => { c.width = 0; if (b) resolve(b); else reject(new Error('png')); }, 'image/png');
    };
    im.onerror = () => reject(new Error('svg'));
    im.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(iconSvg(ic, color, stroke, size));
  });
}
